                            q.append((nx, ny))
                comps.append(cells)

    if not comps:
        return out

    # Decorations associated to a component: adjacent nonzero non-4 cells
    def get_decorations(cells):
        s = set(cells)
        dec = {}
        for r, c in cells:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in s:
                    v = grid[nr][nc]
                    if v in (1, 2, 3):
                        dec[(nr, nc)] = v
        return dec

    comp_infos = []
    for cells in comps:
        dec = get_decorations(cells)
        colors = set(dec.values())
        comp_infos.append((cells, dec, colors))

    # Source is the one containing both 1 and 3 decorations
