            transformed = [tf(r, c) for r, c in src_list]
            for sr, sc in transformed:
                for tr, tc in tgt_set:
                    dr, dc = tr - sr, tc - sc
                    mapped = {(r + dr, c + dc) for r, c in transformed}
                    if mapped == tgt_set:
                        return tf, dr, dc
        return None

    for i, (target_cells, _, _) in enumerate(comp_infos):
        if i == source_idx:
            continue

        mapping = find_mapping(source_cells, target_cells)
        if mapping is None:
